package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.view.inspector.WindowInspector;import android.widget.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.Test;import java.io.*;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Private saved records; real quantity/rename/delete controls, no service or effects. */
public final class TagManagementFlowTest {
 final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);final List<Activity> owned=new CopyOnWriteArrayList<>();Activity activity;Records.Factory factory;String database;long record;
 interface Check{boolean ready()throws Exception;}void waitFor(Check condition)throws Exception{long end=SystemClock.elapsedRealtime()+12000;while(!condition.ready()){if(SystemClock.elapsedRealtime()>end)throw new AssertionError("Saved tag state did not become ready");Thread.sleep(30);}}
 View root(){for(View view:WindowInspector.getGlobalWindowViews())if(view.hasWindowFocus()&&view.isAttachedToWindow()&&view.getContext().getPackageName().equals(c.getPackageName()))return view;return null;}
 View find(View view,String label){if(view==null)return null;if(label.contentEquals(view.getContentDescription()==null?"":view.getContentDescription())||view instanceof TextView&&label.contentEquals(((TextView)view).getText()))return view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int n=0;n<group.getChildCount();n++){View child=find(group.getChildAt(n),label);if(child!=null)return child;}}return null;}
 Rect bounds(String label){Rect[] found={null};i.runOnMainSync(()->{View view=find(root(),label);while(view!=null&&!view.isClickable())view=view.getParent() instanceof View?(View)view.getParent():null;if(view==null||!view.isEnabled())return;Rect rect=new Rect();if(view.getGlobalVisibleRect(rect)&&rect.height()==view.getHeight()&&rect.width()==view.getWidth()&&rect.height()>=Design.dp(c,48)){int[] position=new int[2];view.getLocationOnScreen(position);found[0]=new Rect(position[0],position[1],position[0]+view.getWidth(),position[1]+view.getHeight());}else view.requestRectangleOnScreen(new Rect(0,0,view.getWidth(),view.getHeight()),false);});return found[0];}
 void click(String label)throws Exception{waitFor(()->bounds(label)!=null);View[] owner={null};CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{owner[0]=root();assertNotNull(owner[0]);owner[0].getViewTreeObserver().registerFrameCommitCallback(frame::countDown);owner[0].invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));Rect rect=bounds(label);assertNotNull(label,rect);i.runOnMainSync(()->assertSame("Input belongs to the committed focused window",owner[0],root()));assertTrue(d.click(rect.centerX(),rect.centerY()));}
 void text(String label)throws Exception{waitFor(()->{boolean[] result={false};i.runOnMainSync(()->result[0]=find(root(),label)!=null);return result[0];});}
 void input(String label,String value)throws Exception{UiObject2 field=d.wait(Until.findObject(By.desc(label)),4000);assertNotNull(label,field);field.setText(value);}
 boolean ime(){boolean[] visible={false};i.runOnMainSync(()->{View root=root();WindowInsets insets=root==null?null:root.getRootWindowInsets();visible[0]=insets!=null&&insets.isVisible(WindowInsets.Type.ime());});return visible[0];}void finishInput(String title)throws Exception{if(ime()){assertTrue(d.pressBack());waitFor(()->!ime());}text(title);}
 File folder(){File f=new File(c.getExternalFilesDir(null),"verification");assertTrue(f.isDirectory()||f.mkdirs());return f;}void capture(String name,String label)throws Exception{text(label);CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{View root=root();assertNotNull(root);root.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);root.invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));assertTrue(d.takeScreenshot(new File(folder(),"tags-"+name+".png")));}
 void launchEditor()throws Exception{Activity owner=i.startActivitySync(new Intent(c,RecordEditorActivity.class).putExtra("record",record).putExtra("visualReview",true).putExtra("verificationLabel","TEST FIXTURE · saved tag quantities").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));activity=owner;waitFor(owner::hasWindowFocus);text("Set tag quantity");}
 boolean belongsTo(View view,Activity owner){if(view==null)return false;Context context=view.getContext();while(context!=null){if(context==owner)return true;if(!(context instanceof ContextWrapper))break;Context base=((ContextWrapper)context).getBaseContext();if(base==context)break;context=base;}if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int n=0;n<group.getChildCount();n++)if(belongsTo(group.getChildAt(n),owner))return true;}return false;}
 void recreate()throws Exception{Activity previous=activity;i.runOnMainSync(previous::recreate);waitFor(()->{boolean[] ready={false};i.runOnMainSync(()->ready[0]=activity!=previous&&!activity.isDestroyed()&&belongsTo(root(),activity));return ready[0];});}
 @Test public void quantityDraftSaveRenameDeleteAndComparisonPersist()throws Exception{
  assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(TrackingService.running);assertFalse(AlarmService.active);assertFalse(Prefs.flag(c,"ringing"));String original;try(Store store=new Store(c)){original=BackupFingerprint.read(store);}Map<String,?> preferences=new HashMap<>(Prefs.of(c).getAll());Records.Factory previous=Records.factory;database="tags-ui-"+UUID.randomUUID()+".db";factory=context->new Store(context,database);Records.factory=factory;long now=System.currentTimeMillis(),end=now-86400000;try(Store store=factory.open(c)){RecordDraft tagged=new RecordDraft(end-6*3600000,end);tagged.addTag("Coffee");record=Records.create(store,tagged,java.time.ZoneId.of("UTC"),now);Records.create(store,new RecordDraft(end-86400000-8*3600000,end-86400000),java.time.ZoneId.of("UTC"),now);}
  Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){owned.add(a);}public void onActivityResumed(Activity a){activity=a;}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(callbacks);boolean quiet=false;
  try{launchEditor();click("Set tag quantity");click("Coffee");input("Tag quantity","2.5");input("Quantity unit","cups");finishInput("Coffee quantity");capture("quantity-draft","Use quantity");
   recreate();
   text("Coffee quantity");assertEquals("2.5",d.findObject(By.desc("Tag quantity")).getText());assertEquals("cups",d.findObject(By.desc("Quantity unit")).getText());capture("quantity-recreated","Use quantity");click("Use quantity");capture("editor","Save changes");click("Save changes");waitFor(()->activity instanceof HistoryActivity);try(Store store=factory.open(c)){assertEquals(new TagQuantity(2.5,"cups"),Records.get(store,record).edit.quantities.get("Coffee"));}
   launchEditor();click("Manage saved tags");text("Tags & sleep");waitFor(()->!TagJobs.get(c,factory).state.busy&&TagJobs.get(c,factory).state.impacts.containsKey("Coffee"));capture("comparison","Rename tag");click("Rename tag");input("New tag name","Caffeine");finishInput("Rename tag");capture("rename","Save tag name");click("Cancel");try(Store store=factory.open(c)){assertTrue(Records.get(store,record).edit.tags.contains("Coffee"));}click("Rename tag");input("New tag name","Caffeine");finishInput("Rename tag");click("Save tag name");waitFor(()->!TagJobs.get(c,factory).state.busy&&TagJobs.get(c,factory).state.impacts.containsKey("Caffeine"));recreate();text("Caffeine");capture("renamed","Rename tag");try(Store store=factory.open(c)){assertEquals(new TagQuantity(2.5,"cups"),Records.get(store,record).edit.quantities.get("Caffeine"));}
   click("Delete tag from records");capture("delete-confirm","Delete tag");click("Cancel");assertTrue(TagJobs.get(c,factory).state.impacts.containsKey("Caffeine"));click("Delete tag from records");click("Delete tag");waitFor(()->!TagJobs.get(c,factory).state.busy&&TagJobs.get(c,factory).state.impacts.isEmpty());text("No saved tags yet");capture("deleted","No saved tags yet");try(Store store=factory.open(c)){assertEquals(2,Records.all(store).size());assertTrue(Records.get(store,record).edit.tags.isEmpty());assertTrue(Records.get(store,record).edit.quantities.isEmpty());}
  }catch(Exception|AssertionError failure){try{d.takeScreenshot(new File(folder(),"tags-failure.png"));d.dumpWindowHierarchy(new File(folder(),"tags-failure.xml"));}catch(Exception screenshot){failure.addSuppressed(screenshot);}throw failure;}
  finally{try{RecordSaves.drain(10000);TagJobs.drain(factory);waitFor(()->{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed()&&!a.isFinishing())a.finish();});return owned.stream().allMatch(Activity::isDestroyed);});for(Activity a:owned){if(a instanceof RecordEditorActivity)((RecordEditorActivity)a).awaitReaders(10000);if(a instanceof HistoryActivity)((HistoryActivity)a).awaitReaders(10000);}TagJobs.drain(factory);TagJobs.forget(factory);quiet=true;}finally{app.unregisterActivityLifecycleCallbacks(callbacks);Records.factory=previous;try(Store store=new Store(c)){assertEquals(original,BackupFingerprint.read(store));}assertEquals(preferences,Prefs.of(c).getAll());if(quiet)c.deleteDatabase(database);}}
 }
}
